style.css:
@-moz-document domain("www.notion.so") {
/* יישור טקסט מימין לשמאל */
    body, .notion-page-content, .notion-selectable, .notion-callout-block, .notion-collection-item {
        direction: rtl !important;
        text-align: right !important;
    }

    /* קוד ב-Notion מיישור משמאל לימין */
    pre, code, .notion-code-block, .notion-code {
        direction: ltr !important;
        text-align: left !important;
    }
}
